    const bot = this.bot;
    const owner = playerOf(bot, this.options.owner);
    const activity = this.activity ? `\uFF0C\u6B63\u5728 ${this.activity.name}\uFF08${Math.round((Date.now() - this.activity.startedAt) / 1e3)} \u79D2\uFF09` : "\uFF0C\u7A7A\u95F2";
